insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('tmua-001','TMUA-Mathematics-Algebra','TMUA','Mathematics','Intermediate','{"text":"The roots of the equation below are α and β. What is the value of α² + β²?","math":"x^2-6x+7=0","subtopic":"Quadratics","tags":["Algebra","Quadratics"],"seconds":90}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-001',0,'14') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-001',1,'22') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-001',2,'29') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-001',3,'36') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-001',4,'43') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('tmua-001',1,'By the sum and product of roots, α + β = 6 and αβ = 7. Therefore α² + β² = (α + β)² − 2αβ = 36 − 14 = 22.','["Use the sum and product of the roots.","Expand (α + β)². Which term needs to be subtracted?","The sum is 6 and the product is 7. Evaluate 6² − 2 × 7."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('tmua-002','TMUA-Mathematics-Sequences','TMUA','Mathematics','Foundation','{"text":"An arithmetic sequence has third term 11 and eighth term 31. What is the sum of its first ten terms?","subtopic":"Arithmetic sequences","tags":["Sequences","Arithmetic sequences"],"seconds":90}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-002',0,'180') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-002',1,'200') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-002',2,'210') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-002',3,'230') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-002',4,'240') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('tmua-002',2,'Five common differences separate the third and eighth terms, so d = (31 − 11)/5 = 4. The first term is 3. The tenth is 39, giving S₁₀ = 10(3 + 39)/2 = 210.','["Find the common difference using the two given terms.","There are five steps between terms 3 and 8.","The first term is 3 and the tenth is 39. Use n(first + last)/2."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('tmua-003','TMUA-Mathematics-Calculus','TMUA','Mathematics','Intermediate','{"text":"At which positive value of x does the following function have a stationary point?","math":"f(x)=x^3-12x+5","subtopic":"Stationary points","tags":["Calculus","Stationary points"],"seconds":75}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-003',0,'1') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-003',1,'2') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-003',2,'3') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-003',3,'4') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-003',4,'6') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('tmua-003',1,'A stationary point has derivative zero. f′(x) = 3x² − 12 = 0 gives x² = 4. The positive solution is x = 2.','["A stationary point occurs when the gradient is zero.","Differentiate each term, then set the result equal to zero.","Solve 3x² − 12 = 0 and select the positive root."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('tmua-004','TMUA-Mathematics-Logic & proof','TMUA','Mathematics','Challenge','{"text":"For integers n, consider the statement: “If n² is even, then n is even.” Which statement is its contrapositive?","subtopic":"Necessary conditions","tags":["Logic & proof","Necessary conditions"],"seconds":100}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-004',0,'If n is even, then n² is even.') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-004',1,'If n² is odd, then n is odd.') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-004',2,'If n is odd, then n² is odd.') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-004',3,'If n is odd, then n² is even.') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-004',4,'n² is even if and only if n is even.') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('tmua-004',2,'The contrapositive of P ⇒ Q is not Q ⇒ not P. Here P means n² is even, and Q means n is even. Thus: if n is odd, then n² is odd.','["The contrapositive reverses the implication and negates both parts.","For P ⇒ Q, write not Q ⇒ not P.","For integers, “not even” means “odd”."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('tmua-005','TMUA-Mathematics-Probability','TMUA','Mathematics','Intermediate','{"text":"A bag contains 4 red balls and 3 blue balls. Two balls are drawn without replacement. What is the probability they have the same colour?","subtopic":"Without replacement","tags":["Probability","Without replacement"],"seconds":90}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-005',0,'2/7') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-005',1,'3/7') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-005',2,'1/2') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-005',3,'4/7') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-005',4,'5/7') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('tmua-005',1,'P(both red) = (4/7)(3/6) = 2/7. P(both blue) = (3/7)(2/6) = 1/7. Add these mutually exclusive outcomes: 3/7.','["Count the two possible ways to have the same colour.","Calculate P(red then red) and P(blue then blue).","Add (4/7)(3/6) and (3/7)(2/6)."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('tmua-006','TMUA-Mathematics-Geometry','TMUA','Mathematics','Foundation','{"text":"A circle has centre (2, −1) and passes through (5, 3). What is its area?","subtopic":"Coordinate geometry","tags":["Geometry","Coordinate geometry"],"seconds":75}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-006',0,'5π') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-006',1,'10π') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-006',2,'16π') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-006',3,'25π') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-006',4,'36π') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('tmua-006',3,'The squared radius is (5 − 2)² + (3 + 1)² = 9 + 16 = 25. The area is πr² = 25π.','["Find the distance from the centre to the given point.","Use Pythagoras for horizontal distance 3 and vertical distance 4.","The radius is 5. The area is π times the radius squared."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('tmua-007','TMUA-Mathematics-Algebra','TMUA','Mathematics','Challenge','{"text":"Find the value of x that satisfies the equation, where x > 2.","math":"\\log_2(x)+\\log_2(x-2)=3","subtopic":"Logarithms","tags":["Algebra","Logarithms"],"seconds":110}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-007',0,'2 + √3') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-007',1,'4') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-007',2,'1 + √7') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-007',3,'1 + √5') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-007',4,'8') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('tmua-007',1,'Combine logarithms to get log₂(x(x − 2)) = 3, hence x² − 2x = 8. Factor (x − 4)(x + 2) = 0. The condition x > 2 leaves x = 4.','["Combine the two logarithms using the product rule.","Rewrite log₂(x(x − 2)) = 3 in exponential form.","Solve x² − 2x − 8 = 0 and check the domain."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('tmua-008','TMUA-Mathematics-Sequences','TMUA','Mathematics','Intermediate','{"text":"A geometric series has first term 6 and common ratio 1/3. What is its sum to infinity?","subtopic":"Geometric series","tags":["Sequences","Geometric series"],"seconds":60}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-008',0,'8') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-008',1,'9') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-008',2,'12') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-008',3,'18') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('tmua-008',4,'27') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('tmua-008',1,'Since |r| < 1, the infinite sum is a/(1 − r) = 6/(1 − 1/3) = 6/(2/3) = 9.','["Check that the common ratio has magnitude below 1.","Use the infinite geometric sum formula a/(1 − r).","Substitute a = 6 and r = 1/3."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('esat-001','ESAT-Mathematics 1-Algebra','ESAT','Mathematics 1','Foundation','{"text":"If 2x + y = 11 and x − y = 1, what is the value of xy?","subtopic":"Simultaneous equations","tags":["Algebra","Simultaneous equations"],"seconds":60}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-001',0,'7') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-001',1,'10') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-001',2,'12') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-001',3,'15') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-001',4,'20') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('esat-001',2,'Add the equations to get 3x = 12, so x = 4. Then y = 3 and xy = 12.','["Eliminate y by adding the equations.","The sum of the two equations is 3x = 12.","Find y using x − y = 1, then multiply."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('esat-002','ESAT-Mathematics 2-Calculus','ESAT','Mathematics 2','Intermediate','{"text":"Evaluate the definite integral.","math":"\\int_0^2 (3x^2+1)\\,dx","subtopic":"Definite integration","tags":["Calculus","Definite integration"],"seconds":75}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-002',0,'6') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-002',1,'8') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-002',2,'10') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-002',3,'12') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-002',4,'14') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('esat-002',2,'An antiderivative is x³ + x. Evaluating between 0 and 2 gives (8 + 2) − 0 = 10.','["Find an antiderivative of each term.","Integrating 3x² gives x³; integrating 1 gives x.","Evaluate x³ + x at 2 and subtract its value at 0."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('esat-003','ESAT-Physics-Mechanics','ESAT','Physics','Foundation','{"text":"A 3 kg object experiences a constant resultant force of 12 N. Starting from rest, what distance does it travel in 2 seconds?","subtopic":"Acceleration","tags":["Mechanics","Acceleration"],"seconds":90}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-003',0,'2 m') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-003',1,'4 m') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-003',2,'6 m') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-003',3,'8 m') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-003',4,'12 m') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('esat-003',3,'Newton’s second law gives a = F/m = 4 m s⁻². From rest, s = ½at² = ½ × 4 × 4 = 8 m.','["Calculate acceleration from force and mass.","Use s = ut + ½at² with u = 0.","The acceleration is 4 m s⁻². Substitute t = 2 s."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('esat-004','ESAT-Physics-Electricity','ESAT','Physics','Intermediate','{"text":"A 6 Ω resistor and a 3 Ω resistor are connected in parallel across a 12 V supply. What is the total current?","subtopic":"Parallel resistance","tags":["Electricity","Parallel resistance"],"seconds":90}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-004',0,'1 A') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-004',1,'2 A') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-004',2,'4 A') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-004',3,'6 A') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-004',4,'9 A') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('esat-004',3,'The equivalent resistance is (6 × 3)/(6 + 3) = 2 Ω. Ohm’s law gives total current I = 12/2 = 6 A.','["Find the equivalent resistance of the parallel combination.","Use 1/R = 1/6 + 1/3.","The equivalent resistance is 2 Ω. Use I = V/R."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('esat-005','ESAT-Chemistry-Amount of substance','ESAT','Chemistry','Foundation','{"text":"What amount of substance is present in 5.85 g of sodium chloride? Use M(NaCl) = 58.5 g mol⁻¹.","subtopic":"Moles","tags":["Amount of substance","Moles"],"seconds":60}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-005',0,'0.01 mol') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-005',1,'0.05 mol') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-005',2,'0.10 mol') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-005',3,'0.50 mol') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-005',4,'1.00 mol') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('esat-005',2,'Amount n = mass/molar mass = 5.85/58.5 = 0.10 mol.','["Relate amount, mass and molar mass.","Use n = m/M.","Divide 5.85 by 58.5."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('esat-006','ESAT-Chemistry-Atomic structure','ESAT','Chemistry','Foundation','{"text":"An ion has 13 protons and 10 electrons. What is its charge?","subtopic":"Ions","tags":["Atomic structure","Ions"],"seconds":45}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-006',0,'3−') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-006',1,'1−') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-006',2,'0') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-006',3,'1+') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-006',4,'3+') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('esat-006',4,'Protons each contribute +1 and electrons −1 in elementary charge units. The net charge is 13 − 10 = +3.','["Compare positive and negative charges.","Subtract the number of electrons from the number of protons.","There are three more protons than electrons."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('esat-007','ESAT-Biology-Cell biology','ESAT','Biology','Foundation','{"text":"An image of a cell is 30 mm wide. The actual cell is 15 μm wide. What is the magnification?","subtopic":"Magnification","tags":["Cell biology","Magnification"],"seconds":75}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-007',0,'×2') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-007',1,'×20') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-007',2,'×200') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-007',3,'×2,000') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-007',4,'×20,000') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('esat-007',3,'Convert 30 mm to 30,000 μm. Magnification = image size/actual size = 30,000/15 = 2,000.','["Convert both measurements to the same units.","One millimetre is 1,000 micrometres.","Divide 30,000 μm by 15 μm."]') on conflict do nothing;
insert into public.questions(id,topic_id,exam,module,difficulty,content,provenance,verified,version) values('esat-008','ESAT-Biology-Genetics','ESAT','Biology','Intermediate','{"text":"Two heterozygous parents (Aa × Aa) have a child. Assuming simple Mendelian inheritance, what is the probability the child is homozygous?","subtopic":"Monohybrid inheritance","tags":["Genetics","Monohybrid inheritance"],"seconds":75}','Stem Studios original · demo collection',true,1) on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-008',0,'1/4') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-008',1,'1/3') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-008',2,'1/2') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-008',3,'2/3') on conflict do nothing;
insert into public.question_options(question_id,position,content) values('esat-008',4,'3/4') on conflict do nothing;
insert into public.question_solutions(question_id,correct_index,solution,hints) values('esat-008',2,'The equally likely outcomes are AA, Aa, aA and aa. AA and aa are homozygous, giving 2/4 = 1/2.','["Draw a 2 × 2 Punnett square.","Homozygous means two identical alleles.","Count AA and aa out of the four outcomes."]') on conflict do nothing;
